1	import { readFileSync } from "node:fs";
2	import { fileURLToPath } from "node:url";
3	import path from "node:path";
4	import { simulate } from "./engine.js";
5	
6	const here = path.dirname(fileURLToPath(import.meta.url));
7	
8	export function getFacts(inputFields) {
9	  if (inputFields) return simulate(inputFields);
10	  return JSON.parse(readFileSync(path.join(here, "fake-facts.json"), "utf8"));
11	}
12	
13	function resolve(facts, key) {
14	  const parts = key.split(".");
15	  let val = facts;
16	  for (const p of parts) {
17	    if (val == null || typeof val !== "object" || !(p in val)) return undefined;
18	    val = val[p];
19	  }
20	  return val;
21	}
22	
23	function humanNumber(val) {
24	  if (typeof val === "boolean") return val ? "yes" : "no";
25	  if (typeof val === "string") return val;
26	  if (typeof val !== "number") return String(val);
27	  if (val >= 1_000_000) return `about $${(val / 1_000_000).toFixed(1)} million`;
28	  if (val >= 1000) return `about $${Math.round(val / 1000).toLocaleString("en-CA")},000`;
29	  if (val > 0 && val < 1) return `${Math.round(val * 100)}%`;
30	  return String(Math.round(val));
31	}
32	
33	const PLACEHOLDER_RE = /\{([a-z0-9_]+(?:\.[a-z0-9_]+)*)\}/g;
34	const RAW_NUMBER_RE = /(?<!\{[\w.]*)\b\d{2,}\b(?![\w.]*\})/;
35	
36	export function fillPlaceholders(template, facts) {
37	  if (RAW_NUMBER_RE.test(template)) {
38	    return { ok: false, error: "raw_number", text: template };
39	  }
40	
41	  const unknown = [];
42	
43	  const filled = template.replace(PLACEHOLDER_RE, (_match, key) => {
44	    const val = resolve(facts, key);
45	    if (val === undefined) {
46	      unknown.push(key);
47	      return `{${key}}`;
48	    }
49	    return humanNumber(val);
50	  });
