#!/usr/bin/env node
/**
 * 200-conversation grounding test: fine-tuned model vs Gemini vs base.
 * Measures: invented numbers, placeholder validity, rewrite rate, latency.
 * Usage: node words/grounding-test.js
 * Needs: MODEL_URL, GEMINI_API_KEY in env or .env
 */

import { simulate } from "../sim/engine.js";
import { fillPlaceholders } from "../sim/facts.js";
import { checkSentence, writeReply } from "../voice/chat.js";
import { readFileSync } from "fs";

try {
  const env = readFileSync(".env", "utf8");
  for (const line of env.split("\n")) {
    const m = line.match(/^([A-Z_]+)=(.+)$/);
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
  }
} catch {}

const MODEL_URL = process.env.MODEL_URL;
const GEMINI_KEY = process.env.GEMINI_API_KEY;

const NAMES = ["Ethan", "Sarah", "Marcus", "Priya", "James", "Olivia", "Wei", "Aisha", "Carlos", "Emma",
  "Noah", "Fatima", "Liam", "Yuki", "Ava", "Omar", "Chloe", "Raj", "Mia", "Jamal"];
const QUESTIONS = [
  "Did I end up okay with money?",
  "How much did I save by the time I was seventy?",
  "Was I healthy?",
  "Did I retire comfortably?",
  "What's the one thing I should change?",
  "How long did I live?",
  "Did my savings last?",
  "Was I able to travel?",
  "Did I have enough for retirement?",
  "What would you tell me about my health?",
  "Should I save more?",
  "How are my healthy years looking?",
  "Did exercise make a difference?",
  "What about my income in retirement?",
  "Any regrets about money?",
  "Was quitting smoking worth it?",
  "Did I ever run out of money?",
  "How did my habits affect me?",
  "What's the best financial decision I made?",
  "Tell me about my future.",
];

function randInt(lo, hi) { return lo + Math.floor(Math.random() * (hi - lo + 1)); }
function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }

function randomProfile() {
  return {
    name: pick(NAMES),
    age: randInt(18, 35),
    sex: Math.random() < 0.5 ? "male" : "female",
    province: "ON",
    income_per_year: randInt(20000, 120000),
    savings: { tfsa: randInt(0, 20000), rrsp: randInt(0, 15000), other: randInt(0, 5000) },
    saving_per_month: randInt(0, 500),
    retirement_age: randInt(60, 70),
    habits: {
      exercise_per_week: randInt(0, 7),
      sleep_hours: randInt(4, 9),
      smoker: Math.random() < 0.2,
      drinks_per_week: randInt(0, 15),
    },
  };
}

function gradeReply(sentences, facts) {
  let good = 0, bad = 0, rewrite = 0;
  for (const s of sentences) {
    if (checkSentence(s, facts)) {
      const filled = fillPlaceholders(s, facts);
      if (filled.ok) good++;
      else bad++;
    } else {
      bad++;
      rewrite++;
    }
  }
  return { good, bad, rewrite, total: sentences.length };
}

async function callFineTuned(question, facts, name) {
  if (!MODEL_URL) return null;
  const keys = Object.keys(flattenFacts(facts));
  const start = Date.now();
  const res = await fetch(`${MODEL_URL}/chat/completions`, {
    method: "POST",
    signal: AbortSignal.timeout(8000),
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      messages: [
        { role: "system", content: `You are ${name} at age 70. Reply warmly in 1-3 sentences. Never write any digit or number word. Use only these placeholders: ${keys.map(k => `{${k}}`).join(", ")}. Reply as JSON: {"sentences": ["...", "..."]}` },
        { role: "user", content: question },
      ],
      temperature: 0.7,
      max_tokens: 300,
    }),
  });
  const latency = Date.now() - start;
  const body = await res.json();
  const text = body?.choices?.[0]?.message?.content ?? "";
  let sentences;
  try { sentences = JSON.parse(text).sentences; } catch {}
  if (!Array.isArray(sentences)) sentences = text.split(/(?<=[.!?])\s+/).filter(Boolean).slice(0, 4);
  return { sentences: sentences.map(String), latency };
}

function flattenFacts(facts) {
  const out = {};
  const walk = (obj, prefix) => {
    for (const [k, v] of Object.entries(obj ?? {})) {
      if (k === "sources") continue;
      const path = prefix ? `${prefix}.${k}` : k;
      if (v && typeof v === "object" && !Array.isArray(v)) walk(v, path);
      else if (typeof v === "number" || typeof v === "string") out[path] = v;
    }
  };
  walk(facts, "");
  return out;
}

async function callGemini(question, facts, name) {
  if (!GEMINI_KEY) return null;
  const start = Date.now();
  const sentences = await writeReply({
    question, facts, name,
    apiKey: GEMINI_KEY,
    timeoutMs: 8000,
  });
  return { sentences, latency: Date.now() - start };
}

async function main() {
  const N = 200;
  const results = { finetune: { pass: 0, fail: 0, rewrites: 0, total: 0, latencies: [] },
                    gemini:   { pass: 0, fail: 0, rewrites: 0, total: 0, latencies: [] } };

  console.log(`Running ${N} conversations...`);
  for (let i = 0; i < N; i++) {
    const profile = randomProfile();
    const facts = simulate(profile);
    const question = pick(QUESTIONS);

    // Fine-tuned model
    if (MODEL_URL) {
      try {
        const r = await callFineTuned(question, facts, profile.name);
        if (r) {
          const g = gradeReply(r.sentences, facts);
          results.finetune.pass += g.good;
          results.finetune.fail += g.bad;
          results.finetune.rewrites += g.rewrite;
          results.finetune.total += g.total;
          results.finetune.latencies.push(r.latency);
        }
      } catch (e) { results.finetune.fail++; results.finetune.total++; }
    }

    // Gemini
    if (GEMINI_KEY) {
      try {
        const r = await callGemini(question, facts, profile.name);
        if (r) {
          const g = gradeReply(r.sentences, facts);
          results.gemini.pass += g.good;
          results.gemini.fail += g.bad;
          results.gemini.rewrites += g.rewrite;
          results.gemini.total += g.total;
          results.gemini.latencies.push(r.latency);
        }
      } catch (e) { results.gemini.fail++; results.gemini.total++; }
    }

    if ((i + 1) % 20 === 0) process.stdout.write(`  ${i + 1}/${N}\n`);
  }

  console.log("\n=== GROUNDING TEST RESULTS (200 conversations) ===\n");

  for (const [label, r] of [["Fine-tuned", results.finetune], ["Gemini", results.gemini]]) {
    if (r.total === 0) { console.log(`${label}: skipped (no key/url)`); continue; }
    const passRate = ((r.pass / r.total) * 100).toFixed(1);
    const rewriteRate = ((r.rewrites / r.total) * 100).toFixed(1);
    const sorted = r.latencies.slice().sort((a, b) => a - b);
    const median = sorted[Math.floor(sorted.length / 2)] || 0;
    const p95 = sorted[Math.floor(sorted.length * 0.95)] || 0;
    console.log(`${label}:`);
    console.log(`  Sentences with zero invented numbers: ${r.pass}/${r.total} (${passRate}%)`);
    console.log(`  Sentences needing rewrite: ${r.rewrites}/${r.total} (${rewriteRate}%)`);
    console.log(`  Latency median: ${median} ms, p95: ${p95} ms`);
    console.log();
  }
}

main().catch(console.error);

