1	// The /voice WebSocket (CONTRACTS.md "Voice pipeline").
2	//
3	// Built:
4	//   client -> {type:"start", name, sex, apparent_age}   begins a session; we greet by name
5	//   client -> {type:"text", question}                   a typed or confirmed question
6	//   client -> {type:"age", apparent_age}                slider moved; next sentences use it
7	//   server -> {type:"reply", sentence, audio, sampleRate, done}   one per sentence (+ ms: delay)
8	//   server -> {type:"status", state}                    listening | thinking | speaking
9	//   server -> {type:"error", feature, message}
10	//   reply.audio is null when the voice is off: the headset shows text only (text fallback).
11	//   client -> {type:"audio", data, sampleRate}         mic audio (16-bit mono PCM, 16000 Hz) streamed continuously
12	//   server -> {type:"transcript", text}                what the person said, sent when they stop talking
13	// Mic audio is dropped while the future self is still talking (plus a short tail), so the
14	// headset's mic can't hear the speakers and make Uncle answer itself.
15	import { WebSocketServer } from "ws";
16	import { speak as realSpeak } from "../voice/tts.js";
17	import { applyAging } from "../voice/filter.js";
18	import { agingParams, strengthForAge } from "../voice/aging.js";
19	import { floatToPcm16 } from "../voice/wav.js";
20	import { createStore } from "../voice/store.js";
21	import { createSttSession } from "../voice/stt.js";
22	import { loadSamples, clipFor } from "../voice/samples.js";
23	import { getFacts as realGetFacts } from "../sim/facts.js";
24	import { reply, replyStream, greeting } from "./brain.js";
25	
26	const SPEAK_TIMEOUT_MS = 4000;
27	const MAX_QUESTION = 500;
28	
29	function send(ws, obj) {
30	  if (ws.readyState === ws.OPEN) ws.send(JSON.stringify(obj));
31	}
32	
33	// The simulation's merge lets a nested null overwrite one of its defaults (for example
34	// habits.drinks_per_week: null), so send it only the fields the person actually gave us.
35	export function dropNulls(obj) {
36	  if (Array.isArray(obj) || obj === null || typeof obj !== "object") return obj;
37	  const out = {};
38	  for (const [k, v] of Object.entries(obj)) {
39	    if (v === null || v === undefined) continue;
40	    const cleaned = dropNulls(v);
41	    if (cleaned !== null && typeof cleaned === "object" && !Array.isArray(cleaned) && Object.keys(cleaned).length === 0) continue;
42	    out[k] = cleaned;
43	  }
44	  return out;
45	}
46	
47	const clampAge = (n) => (Number.isFinite(Number(n)) ? Math.min(100, Math.max(20, Number(n))) : null);
48	
49	export function attachVoice(httpServer, { speakFn = realSpeak, getFacts = realGetFacts, store = createStore(), sttFactory = createSttSession, writeFn, samples = loadSamples(), streamReplies = process.env.STREAM_REPLY === "1" } = {}) {
50	  const wss = new WebSocketServer({ server: httpServer, path: "/voice", maxPayload: 4 * 1024 * 1024 });
51	
52	  wss.on("connection", (ws) => {
53	    // What we know about this person, set by the "start" message.
54	    const session = { name: null, sex: "neutral", apparentAge: null, voiceId: undefined, facts: null, history: [], speech: "" };
55	    let queue = Promise.resolve(); // one reply at a time, in order
56	    let stt = null; // speech-to-text session, opened when mic audio first arrives
57	    let playbackUntil = 0; // when the headset will finish playing what we last sent (ms clock)
58	
59	    // Speak with the person's own clone; if that fails, fall back to the stock voice so the
60	    // conversation keeps going (PLAN.md: "if cloning fails, a ready-made voice, then text").
61	    // A slow ElevenLabs call must not stall the conversation: after SPEAK_TIMEOUT_MS give up on the clone.
62	    const withTimeout = (promise, ms, what) =>
63	      Promise.race([promise, new Promise((_, reject) => setTimeout(() => reject(new Error(`${what} took longer than ${ms} ms`)), ms).unref())]);
64	    async function speakOne(sentence) {
65	      try {
66	        try {
67	          return await withTimeout(speakFn(sentence, { voiceId: session.voiceId }), SPEAK_TIMEOUT_MS, "voice");
68	        } catch (err) {
69	          if (!session.voiceId) throw err;
70	          return await withTimeout(speakFn(sentence, {}), SPEAK_TIMEOUT_MS, "stock voice");
71	        }
72	      } catch (err) {
73	        // The speech service is down or out of credits: play a pre-recorded line if we have one, else text only.
74	        const clip = clipFor(samples, sentence);
75	        if (!clip) throw err;
76	        return { samples: clip.samples, sampleRate: clip.sampleRate, clipText: clip.text };
77	      }
78	    }
79	
80	    // Sends one sentence (waiting for its speech job), aged, in order. Shared by the batch and streaming paths.
81	    function makeEmitter(meta) {
82	      const started = performance.now();
83	      const facts = session.facts ?? getFacts();
84	      const strength = strengthForAge(session.apparentAge ?? facts.apparent_age_at_70);
85	      let reportedError = false;
86	      let spoke = false;
87	      let n = 0;
88	      return async (sentence, job, done) => {
89	        const { tts, error } = await job;
90	        let audio = null;
91	        let sampleRate = 24000;
92	        if (tts) {
93	          const aged = applyAging(tts.samples, tts.sampleRate, agingParams(strength, session.sex));
94	          audio = floatToPcm16(aged).toString("base64");
95	          sampleRate = tts.sampleRate;
96	          if (tts.clipText && !reportedError) (reportedError = true), send(ws, { type: "error", feature: "voice", message: "live voice is unavailable; playing recorded lines where we have them" });
97	          if (!spoke) (spoke = true), send(ws, { type: "status", state: "speaking" });
98	          // Remember how long this will play, so mic audio during it is ignored (echo guard).
99	          playbackUntil = Math.max(playbackUntil, performance.now()) + (aged.length / tts.sampleRate) * 1000;
100	        } else if (!reportedError) {
101	          reportedError = true;
102	          send(ws, { type: "error", feature: "voice", message: error?.message ?? "voice failed" });
103	        }
104	        const first = n++ === 0;
105	        const m = typeof meta === "function" ? meta() : meta;
106	        send(ws, {
107	          type: "reply",
108	          sentence: tts?.clipText ?? sentence, // a recorded clip says its own words
109	          audio,
110	          sampleRate,
111	          done,
112	          ms: Math.round(performance.now() - started),
113	          ...(first && m ? { timing: { thinkMs: m.thinkMs, source: m.source } } : {}),
114	        });
115	        if (first && m) console.log(`[voice] reply: write ${m.thinkMs} ms (${m.source}${m.streamed ? ", streamed" : ""}), first sentence spoken ${Math.round(performance.now() - started)} ms later${session.voiceId ? " (clone)" : " (stock)"}`);
116	      };
117	    }
118	
119	    // Write the answer (model or Gemini, checked; keyword stand-in if that fails), remember the exchange, speak it.
120	    async function respond(question) {
121	      send(ws, { type: "status", state: "thinking" });
122	      const facts = session.facts ?? getFacts();
123	      const t0 = performance.now();
124	      if (streamReplies) return respondStreaming(question, facts, t0);
125	      const { sentences, source } = await reply(question, facts, { history: session.history, name: session.name, speech: session.speech, writeFn });
126	      const thinkMs = Math.round(performance.now() - t0);
127	      session.history.push({ role: "you", text: question }, { role: "future", text: sentences.join(" ") });
128	      session.history = session.history.slice(-12);
129	      return say(sentences, { thinkMs, source });
130	    }
131	
132	    // Streaming: each sentence is checked and starts being spoken the moment the model finishes writing it.
133	    // The reply ends with an empty sentence marked done (the count is not known until the model stops).
134	    async function respondStreaming(question, facts, t0) {
135	      let meta = null;
136	      const emit = makeEmitter(() => meta);
137	      const spoken = [];
138	      let chain = Promise.resolve();
139	      for await (const { sentence, source } of replyStream(question, facts, { history: session.history, name: session.name, speech: session.speech, writeFn })) {
140	        if (!meta) meta = { thinkMs: Math.round(performance.now() - t0), source, streamed: source === "model" };
141	        spoken.push(sentence);
142	        const job = speakOne(sentence).then((tts) => ({ tts }), (error) => ({ error }));
143	        chain = chain.then(() => emit(sentence, job, false));
