147	      session.history.push({ role: "you", text: question }, { role: "future", text: spoken.join(" ") });
148	      session.history = session.history.slice(-12);
149	      send(ws, { type: "status", state: "listening" });
150	    }
151	
152	    async function say(sentences, meta) {
153	      send(ws, { type: "status", state: "thinking" });
154	      const emit = makeEmitter(meta);
155	      // Start every sentence's speech at once, then send in order: sentence 1 plays while 2 and 3 are made.
156	      const jobs = sentences.map((s) => speakOne(s).then((tts) => ({ tts }), (error) => ({ error })));
157	      for (let i = 0; i < sentences.length; i++) await emit(sentences[i], jobs[i], i === sentences.length - 1);
158	      send(ws, { type: "status", state: "listening" });
159	    }
160	
161	    function openStt() {
162	      try {
