/* Layout */
nav { padding: 0 24px; height: 64px; display: flex; align-items: center; justify-content: space-between; }
nav .wordmark { font: 500 18px/1 'Inter', sans-serif; color: var(--ink); text-decoration: none; letter-spacing: -0.2px; }
nav .links { display: flex; gap: 20px; }
nav .links a { font: 500 15px/1.4 'Inter', sans-serif; color: var(--muted); text-decoration: none; transition: color 300ms; }
nav .links a:hover { color: var(--ink); }

.stage { flex: 1; display: flex; align-items: center; justify-content: center; padding: 48px 24px 96px; }
.pane {
  max-width: 440px;
  width: 100%;
  text-align: center;
  opacity: 0;
  transform: translateY(12px);
  transition: opacity 500ms ease, transform 500ms ease;
  display: none;
}
.pane.on {
  display: block;
  opacity: 1;
  transform: translateY(0);
}
.pane.leaving {
  opacity: 0;
  transform: translateY(-8px);
}

/* Typography */
h1 {
  font: 300 48px/1.08 'EB Garamond', 'Times New Roman', serif;
  letter-spacing: -0.96px;
  color: var(--ink);
  margin-bottom: 16px;
}
h2 {
  font: 300 32px/1.13 'EB Garamond', 'Times New Roman', serif;
  letter-spacing: -0.32px;
  color: var(--ink);
  margin-bottom: 12px;
}
.subtitle {
  font: 400 16px/1.5 'Inter', sans-serif;
  color: var(--body);
  letter-spacing: 0.16px;
  margin-bottom: 32px;
}
.quiet {
  font: 400 14px/1.5 'Inter', sans-serif;
  color: var(--muted);
  letter-spacing: 0;
}

/* Buttons */
.btn {
  display: inline-block;
  font: 500 15px/1 'Inter', sans-serif;
  letter-spacing: 0;
  padding: 12px 28px;
  border-radius: 9999px;
  border: none;

