178	      position: fixed;
179	      bottom: 24px;
180	      right: 24px;
181	      font: 500 13px/1 'Inter', sans-serif;
182	      color: var(--muted);
183	      background: var(--surface-card);
184	      border: 1px solid var(--hairline);
185	      border-radius: 9999px;
186	      padding: 8px 16px;
187	      cursor: pointer;
188	      z-index: 10;
189	      transition: color 200ms, border-color 200ms;
190	    }
191	    .sound-toggle:hover { color: var(--ink); border-color: var(--hairline-strong); }
192	
193	    @media (prefers-reduced-motion: reduce) {
194	      .pane { transition: none; }
195	      .orb { display: none; }
196	    }
197	    @media (max-width: 640px) {
198	      h1 { font-size: 32px; letter-spacing: -0.32px; }
199	      h2 { font-size: 24px; letter-spacing: 0; }
200	      .timer { font-size: 36px; }
201	      .stage { padding: 32px 20px 64px; }
202	      .orb-1 { width: 250px; height: 250px; }
203	      .orb-2 { width: 200px; height: 200px; }
204	      .orb-3 { width: 180px; height: 180px; }
205	    }
206	  </style>
207	</head>
208	<body>
209	
210	<div class="orb orb-1"></div>
211	<div class="orb orb-2"></div>
212	<div class="orb orb-3"></div>
213	
214	<nav>
215	  <a class="wordmark" href="/">Uncle</a>
216	  <div class="links">
217	    <a href="/heads.html">Saved heads</a>
218	  </div>
219	</nav>
220	
221	<div class="stage">
222	
223	  <!-- 0: Hero -->
224	  <div class="pane on" id="s-hero">
225	    <h1>Meet yourself at 70.</h1>
226	    <p class="subtitle">Talk to us for a minute. We build your future self from your own face, voice, and the numbers that matter.</p>
227	    <button class="btn btn-primary" id="begin">Begin</button>
228	    <p class="quiet" style="margin-top: 24px">Not financial or medical advice. Every number names its source.</p>
229	  </div>
230	
231	  <!-- 1: Name -->
232	  <div class="pane" id="s-name">
233	    <button class="btn-back" onclick="show('s-hero')">&larr; Back</button>
234	    <h2>What should your future self call you?</h2>
235	    <p class="subtitle">This is also how we find your saved voice and head scan.</p>
236	    <label class="field">
237	      <span class="label-text">Your name</span>
238	      <input type="text" id="name" autocomplete="given-name" maxlength="40">
239	    </label>
240	    <p class="quiet" style="margin-bottom: 24px">Your recording goes to ElevenLabs (voice) and Google Gemini (reading your answers). It is kept on this server and you can ask us to delete it.</p>
241	    <p class="error-msg" id="e-name"></p>
242	    <button class="btn btn-primary" id="to-record">Continue</button>
243	  </div>
244	
245	  <!-- 2: Record -->
246	  <div class="pane" id="s-record">
247	    <button class="btn-back" onclick="show('s-name')">&larr; Back</button>
248	    <h2>Talk for about a minute.</h2>
249	    <p class="subtitle">Find a quiet spot and hold the microphone close. These questions help:</p>
250	    <ol class="prompts">
251	      <li>Your age, and what you do all day.</li>
252	      <li>Roughly what you earn, what you have saved, and what you put away each month.</li>
253	      <li>How often you exercise, how much you sleep, and whether you smoke or drink.</li>
254	      <li>At what age you'd like to stop working.</li>
255	    </ol>
256	    <p class="timer" id="timer">0:00</p>
257	    <p class="hint" id="rec-hint">At least 30 seconds gives a better copy of your voice.</p>
258	    <p class="error-msg" id="e-record"></p>
259	    <div class="btn-row">
260	      <button class="btn btn-primary" id="rec-start">Start recording</button>
261	      <button class="btn btn-outline" id="rec-stop" disabled>Stop</button>
262	    </div>
263	  </div>
264	
265	  <!-- 3: Processing -->
266	  <div class="pane" id="s-work">
267	    <h2>One moment.</h2>
268	    <p class="progress-text" id="progress">Copying your voice and reading your answers.</p>
269	    <p class="error-msg" id="e-work"></p>
270	    <button class="btn btn-outline" id="retry" hidden>Record again</button>
271	  </div>
272	
273	  <!-- 4: Confirm -->
274	  <div class="pane" id="s-confirm">
275	    <button class="btn-back" onclick="backToRecord()">&larr; Record again</button>
276	    <h2>Did we get this right?</h2>
277	    <p class="subtitle">Fix anything that's wrong. Where a box is empty, we use a typical value for your age.</p>
278	    <details><summary>What we heard</summary><p id="transcript"></p></details>
279	    <div class="grid" id="fields"></div>
280	    <p class="error-msg" id="e-confirm"></p>
281	    <button class="btn btn-primary" id="confirm">This looks right</button>
282	  </div>
283	
284	  <!-- 5: Ready -->
285	  <div class="pane" id="s-done">
286	    <h2>Your future self is ready.</h2>
287	    <p class="subtitle" id="done-note">Put the headset on and say hello.</p>
288	    <div class="btn-row">
289	      <a class="btn btn-primary" id="open-xr" href="#">Open in the headset</a>
290	      <a class="btn btn-outline" id="open-laptop" href="/dev.html">Talk on this screen</a>
291	    </div>
292	    <p class="quiet" style="margin-top: 20px" id="head-note"></p>
293	  </div>
294	
295	</div>
296	
297	<button class="sound-toggle" id="sound-toggle">Sound on</button>
298	
299	<footer><p>Built at Hack Western. <a href="https://github.com/e-yang6/uncle">Source</a></p></footer>
300	
301	<script>
302	const $ = id => document.getElementById(id);
303	const say = (id, t) => { $(id).textContent = t || ""; };
304	
305	// ---- Pane transitions ----
306	let current = "s-hero";
307	function show(id) {
308	  const old = $(current);
309	  const next = $(id);
310	  if (old === next) return;
311	  old.classList.add("leaving");
312	  setTimeout(() => {
313	    old.classList.remove("on", "leaving");
314	    next.classList.add("on");
315	    current = id;
316	  }, 300);
317	}
318	
319	// ---- Pad synth ----
320	let padCtx, padGain, padStarted = false;
321	function startPad() {
322	  if (padStarted) return;
323	  padStarted = true;
324	  padCtx = new AudioContext();
325	  padGain = padCtx.createGain();
326	  padGain.gain.value = 0;
327	  padGain.connect(padCtx.destination);
328	
329	  const filter = padCtx.createBiquadFilter();
330	  filter.type = "lowpass";
331	  filter.frequency.value = 500;
332	  filter.Q.value = 0.7;
333	  filter.connect(padGain);
334	
335	  const lfo = padCtx.createOscillator();
336	  const lfoGain = padCtx.createGain();
337	  lfo.frequency.value = 0.08;
338	  lfoGain.gain.value = 150;
339	  lfo.connect(lfoGain);
340	  lfoGain.connect(filter.frequency);
341	  lfo.start();
342	
343	  const notes = [110, 164.81, 220, 329.63];
344	  for (const freq of notes) {
345	    for (const detune of [-4, 0, 4]) {
346	      const osc = padCtx.createOscillator();
347	      osc.type = "triangle";
348	      osc.frequency.value = freq;
349	      osc.detune.value = detune;
350	      osc.connect(filter);
351	      osc.start();
352	    }
353	  }
354	  padGain.gain.linearRampToValueAtTime(0.035, padCtx.currentTime + 3);
355	  $("sound-toggle").textContent = "Sound on";
356	}
357	
358	let padMuted = false;
359	$("sound-toggle").onclick = () => {
360	  if (!padStarted) { startPad(); return; }
361	  padMuted = !padMuted;
362	  padGain.gain.linearRampToValueAtTime(padMuted ? 0 : 0.035, padCtx.currentTime + 0.5);
363	  $("sound-toggle").textContent = padMuted ? "Sound off" : "Sound on";
364	};
365	
366	// ---- Hero ----
367	$("begin").onclick = () => {
368	  startPad();
369	  show("s-name");
370	};
371	
372	// ---- Name ----
373	let name = "";
374	$("to-record").onclick = () => {
375	  name = $("name").value.trim();
376	  if (!name) return say("e-name", "Please type your name.");
377	  say("e-name", "");
378	  show("s-record");
379	};
380	$("name").addEventListener("keydown", e => e.key === "Enter" && $("to-record").click());
381	
382	// ---- Record ----
383	let recorder, chunks = [], stream, tick, started = 0;
384	const fmt = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
385	
386	$("rec-start").onclick = async () => {
387	  say("e-record", "");
388	  try {
389	    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
390	  } catch {
391	    return say("e-record", "The microphone is blocked. Allow it in your browser and try again.");
392	  }
393	  chunks = [];
394	  recorder = new MediaRecorder(stream);
395	  recorder.ondataavailable = e => e.data.size && chunks.push(e.data);
396	  recorder.onstop = upload;
397	  recorder.start();
398	  started = performance.now();
399	  $("rec-start").disabled = true;
400	  $("rec-stop").disabled = false;
401	  tick = setInterval(() => {
402	    const s = Math.round((performance.now() - started) / 1000);
403	    $("timer").textContent = fmt(s);
404	    $("rec-hint").textContent = s < 30 ? "Keep going. About a minute is ideal." : "Good. Stop whenever you've covered the questions.";
405	    if (s >= 90) stop();
406	  }, 500);
407	};
408	
409	function stop() {
410	  clearInterval(tick);
411	  if (recorder && recorder.state !== "inactive") recorder.stop();
412	  stream?.getTracks().forEach(t => t.stop());
413	  $("rec-stop").disabled = true;
414	}
415	$("rec-stop").onclick = stop;
416	
417	// ---- Upload: voice clone + field extraction in parallel ----
418	let reading = null, voiceOk = true, voiceProblem = "";
419	async function upload() {
420	  show("s-work");
421	  say("e-work", "");
422	  $("retry").hidden = true;
423	  const blob = new Blob(chunks, { type: recorder.mimeType || "audio/webm" });
424	  const post = url => fetch(url, { method: "POST", headers: { "content-type": blob.type }, body: blob });
425	  let cloneRes, readRes;
426	  try {
427	    [cloneRes, readRes] = await Promise.all([
428	      post("/api/voice/clone?name=" + encodeURIComponent(name)),
429	      post("/api/interview/extract"),
430	    ]);
431	  } catch {
432	    return failed("Could not reach the server. Check your connection and record again.");
433	  }
434	  const c = await cloneRes.json().catch(() => ({}));
435	  reading = await readRes.json().catch(() => ({}));
436	  if (!readRes.ok) return failed("Could not read your answers: " + (reading.error || readRes.status));
437	  voiceOk = cloneRes.ok;
438	  voiceProblem = cloneRes.ok ? "" : "Your voice could not be copied (" + (c.error || cloneRes.status) + "), so Uncle will use a stock voice.";
439	  showConfirm(reading);
440	}
441	
442	function failed(msg) {
443	  say("e-work", msg);
444	  say("progress", "");
445	  $("retry").hidden = false;
446	}
447	$("retry").onclick = () => { backToRecord(); };
448	function backToRecord() { $("timer").textContent = "0:00"; $("rec-start").disabled = false; show("s-record"); }
449	
450	// ---- Confirm ----
451	const ROWS = [
452	  ["age", "Age", "number"], ["sex", "Sex", "select:male,female"], ["province", "Province", "text"],
453	  ["income_per_year", "Income/year ($)", "number"], ["savings.tfsa", "TFSA ($)", "number"],
454	  ["savings.rrsp", "RRSP ($)", "number"], ["savings.other", "Other savings ($)", "number"],
455	  ["saving_per_month", "Saving/month ($)", "number"], ["retirement_age", "Retire at", "number"],
456	  ["habits.exercise_per_week", "Workouts/week", "number"], ["habits.sleep_hours", "Sleep (hours)", "number"],
457	  ["habits.smoker", "Smoker", "select:no,yes"], ["habits.drinks_per_week", "Drinks/week", "number"],
458	];
459	const getPath = (o, p) => p.split(".").reduce((a, k) => a == null ? a : a[k], o);
460	const setPath = (o, p, v) => { const ks = p.split("."); const last = ks.pop(); ks.reduce((a, k) => (a[k] ??= {}), o)[last] = v; };
461	
462	function showConfirm(r) {
463	  $("transcript").textContent = r.transcript || "";
464	  $("fields").replaceChildren();
465	  for (const [path, label, type] of ROWS) {
466	    const heard = getPath(r.heard || {}, path);
467	    const row = document.createElement("label");
468	    row.className = "field";
469	    const span = document.createElement("span");
470	    span.className = "label-text";
471	    span.textContent = label;
472	    row.append(span);
473	    let input;
474	    if (type.startsWith("select:")) {
475	      input = document.createElement("select");
476	      const blank = document.createElement("option");
477	      blank.value = ""; blank.textContent = "Not said";
478	      input.append(blank);
479	      for (const o of type.slice(7).split(",")) input.append(new Option(o, o));
480	      input.value = heard == null ? "" : typeof heard === "boolean" ? (heard ? "yes" : "no") : heard;
481	    } else {
482	      input = document.createElement("input");
483	      input.type = type;
484	      input.placeholder = "Not said";
485	      input.value = heard ?? "";
486	    }
487	    input.dataset.path = path;
488	    row.append(input);
489	    $("fields").append(row);
490	  }
491	  say("e-confirm", [voiceProblem, r.rejected?.length ? "Could not parse: " + r.rejected.join(", ") : ""].filter(Boolean).join(" "));
492	  show("s-confirm");
493	}
494	
495	let savedSex = "";
496	$("confirm").onclick = async () => {
497	  const profile = {};
498	  for (const el of document.querySelectorAll("#fields [data-path]")) {
499	    let v = el.value.trim();
500	    if (v === "") v = null;
501	    else if (el.dataset.path === "habits.smoker") v = v === "yes";
502	    else if (el.type === "number") v = Number(v);
503	    setPath(profile, el.dataset.path, v);
504	  }
505	  savedSex = profile.sex || "";
506	  $("confirm").disabled = true;
507	  const res = await fetch("/api/interview/confirm", {
508	    method: "POST",
509	    headers: { "content-type": "application/json" },
510	    body: JSON.stringify({ name, profile, speech: $("transcript").textContent }),
511	  }).catch(() => null);
512	  const j = res ? await res.json().catch(() => ({})) : {};
513	  $("confirm").disabled = false;
514	  if (!res || !res.ok) return say("e-confirm", "Could not save: " + (j.error || (res ? res.status : "no connection")));
515	  finish();
516	};
517	
518	// ---- Done: hand off to headset ----
519	async function finish() {
520	  const params = new URLSearchParams({ voice: "live", name });
521	  if (savedSex) params.set("sex", savedSex);
522	  let headNote = "No head scan saved yet. The headset will show a stand-in face, but the voice and numbers are yours.";
523	  try {
524	    const { heads } = await (await fetch("/api/heads?q=" + encodeURIComponent(name))).json();
525	    const match = (heads || []).find(h => h.name.toLowerCase() === name.toLowerCase());
526	    if (match) { params.set("head", match.id); headNote = "Your saved head scan will appear across the table."; }
527	  } catch {}
528	  $("open-xr").href = "/xr/?" + params;
529	  $("open-laptop").href = "/dev.html?name=" + encodeURIComponent(name);
530	  say("head-note", headNote + (voiceOk ? "" : " " + voiceProblem));
531	  show("s-done");
532	}
533	</script>
534	</body>
535	</html>
