53	      transform: translateY(12px);
54	      transition: opacity 400ms ease, transform 400ms ease;
55	      pointer-events: none;
56	      visibility: hidden;
57	    }
58	    .pane.on {
59	      position: relative;
60	      opacity: 1;
61	      transform: translateY(0);
62	      pointer-events: auto;
63	      visibility: visible;
64	    }
65	    .pane.entering {
66	      position: relative;
67	      visibility: visible;
68	      pointer-events: none;
69	    }
70	
71	    /* Typography */
72	    h1 {
73	      font: 300 48px/1.08 'EB Garamond', 'Times New Roman', serif;
74	      letter-spacing: -0.96px;
75	      color: var(--ink);
