88	      margin-bottom: 32px;
89	    }
90	    .quiet {
91	      font: 400 14px/1.5 'Inter', sans-serif;
92	      color: var(--muted);
93	      letter-spacing: 0;
94	    }
95	
96	    /* Buttons */
97	    .btn {
98	      display: inline-block;
99	      font: 500 15px/1 'Inter', sans-serif;
100	      letter-spacing: 0;
101	      padding: 12px 28px;
102	      border-radius: 9999px;
103	      border: none;
104	      cursor: pointer;
105	      text-decoration: none;
106	      transition: background 200ms, opacity 200ms;
107	    }
108	    .btn-primary { background: var(--primary); color: var(--on-primary); }
109	    .btn-primary:hover { background: var(--ink); }
110	    .btn-outline { background: transparent; color: var(--ink); border: 1px solid var(--hairline-strong); }
111	    .btn-outline:hover { border-color: var(--ink); }
112	    .btn:disabled { opacity: 0.4; cursor: default; }
113	    .btn:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }
114	    .btn-row { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
115	    .btn-back { background: none; border: none; font: 500 14px/1 'Inter', sans-serif; color: var(--muted); cursor: pointer; padding: 8px 0; margin-bottom: 24px; transition: color 200ms; }
116	    .btn-back:hover { color: var(--ink); }
117	
118	    /* Forms */
119	    label.field { display: block; text-align: left; margin-bottom: 20px; }
120	    label.field .label-text { display: block; font: 400 14px/1.5 'Inter', sans-serif; color: var(--muted); margin-bottom: 6px; }
121	    input[type="text"], input[type="number"], input[type="search"], select {
122	      display: block;
123	      width: 100%;
124	      padding: 12px 16px;
125	      font: 400 16px/1.5 'Inter', sans-serif;
126	      color: var(--ink);
127	      background: var(--surface-card);
128	      border: 1px solid var(--hairline-strong);
129	      border-radius: 8px;
130	      transition: border-color 200ms;
131	    }
132	    input:focus, select:focus { border-color: var(--ink); outline: none; }
133	    select option { color: var(--ink); background: var(--surface-card); }
134	
135	    /* Interview prompts */
136	    .prompts { text-align: left; margin-bottom: 24px; padding-left: 20px; }
137	    .prompts li { margin-bottom: 8px; color: var(--body); font-size: 15px; line-height: 1.47; letter-spacing: 0.15px; }
138	
139	    /* Timer */
140	    .timer { font: 300 48px/1 'EB Garamond', serif; letter-spacing: -0.96px; margin-bottom: 8px; }
141	    .hint { color: var(--muted); font-size: 14px; margin-bottom: 24px; }
142	
143	    /* Confirm grid */
144	    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 16px; text-align: left; }
145	    @media (max-width: 480px) { .grid { grid-template-columns: 1fr; } }
146	    .grid label.field { margin-bottom: 16px; }
147	
148	    /* Error */
149	    .error-msg { color: var(--error); font-size: 14px; min-height: 20px; margin-bottom: 12px; }
150	
