153	
154	    /* Transcript detail */
155	    details { text-align: left; margin-bottom: 20px; }
156	    details summary { font: 500 14px/1.5 'Inter', sans-serif; color: var(--muted); cursor: pointer; }
157	    details p { color: var(--body); font-size: 15px; margin-top: 8px; }
158	
159	    /* Footer */
160	    footer { padding: 24px; text-align: center; }
161	    footer p { font: 400 13px/1.5 'Inter', sans-serif; color: var(--muted-soft); }
