172	      width: 600px; height: 350px;
173	      background: #C8893A;
174	      filter: blur(120px);
175	      border-radius: 40% 60% 55% 45%;
176	      top: -120px; right: -160px;
177	    }
178	    .wash-2 {
179	      width: 450px; height: 500px;
180	      background: #C8893A;
181	      filter: blur(140px);
182	      border-radius: 55% 45% 40% 60%;
