186	
187	    /* Sound toggle */
188	    .sound-toggle {
189	      position: fixed;
190	      bottom: 24px;
191	      right: 24px;
192	      font: 500 13px/1 'Inter', sans-serif;
193	      color: var(--muted);
194	      background: var(--surface-card);
195	      border: 1px solid var(--hairline);
196	      border-radius: 9999px;
197	      padding: 8px 16px;
198	      cursor: pointer;
199	      z-index: 10;
200	      transition: color 200ms, border-color 200ms;
201	    }
202	    .sound-toggle:hover { color: var(--ink); border-color: var(--hairline-strong); }
203	
204	    @media (prefers-reduced-motion: reduce) {
205	      .pane { transition: none; }
206	    }
207	    @media (max-width: 640px) {
208	      h1 { font-size: 32px; letter-spacing: -0.32px; }
209	      h2 { font-size: 24px; letter-spacing: 0; }
210	      .timer { font-size: 36px; }
211	      .stage { padding: 32px 20px 64px; }
212	    }
213	  </style>
214	</head>
215	<body>
216	
217	<div class="wash wash-1"></div>
218	<div class="wash wash-2"></div>
219	
220	<nav>
221	  <a class="wordmark" href="/">Uncle</a>
222	  <div class="links">
223	    <a href="/heads.html">Saved heads</a>
224	  </div>
225	</nav>
226	
227	<div class="stage">
228	
229	  <!-- 0: Hero -->
230	  <div class="pane on" id="s-hero">
231	    <h1>Meet yourself at 70.</h1>
232	    <p class="subtitle">Talk to us for a minute. We build your future self from your own face, voice, and the numbers that matter.</p>
233	    <button class="btn btn-primary" id="begin">Begin</button>
234	  </div>
235	
236	  <!-- 1: Name -->
237	  <div class="pane" id="s-name">
238	    <button class="btn-back" onclick="show('s-hero')">&larr; Back</button>
239	    <h2>What should your future self call you?</h2>
240	    <p class="subtitle">This is also how we find your saved voice and head scan.</p>
241	    <label class="field">
242	      <span class="label-text">Your name</span>
243	      <input type="text" id="name" autocomplete="given-name" maxlength="40">
244	    </label>
245	    <p class="error-msg" id="e-name"></p>
246	    <button class="btn btn-primary" id="to-record">Continue</button>
247	  </div>
248	
249	  <!-- 2: Record -->
250	  <div class="pane" id="s-record">
251	    <button class="btn-back" onclick="show('s-name')">&larr; Back</button>
252	    <h2>Talk for about a minute.</h2>
253	    <p class="subtitle">Find a quiet spot and hold the microphone close. These questions help:</p>
254	    <ol class="prompts">
255	      <li>Your age, and what you do all day.</li>
256	      <li>Roughly what you earn, what you have saved, and what you put away each month.</li>
257	      <li>How often you exercise, how much you sleep, and whether you smoke or drink.</li>
258	      <li>At what age you'd like to stop working.</li>
259	    </ol>
260	    <p class="timer" id="timer">0:00</p>
261	    <p class="hint" id="rec-hint">At least 30 seconds gives a better copy of your voice.</p>
262	    <p class="error-msg" id="e-record"></p>
263	    <div class="btn-row">
264	      <button class="btn btn-primary" id="rec-start">Start recording</button>
265	      <button class="btn btn-outline" id="rec-stop" disabled>Stop</button>
266	    </div>
267	  </div>
268	
269	  <!-- 3: Processing -->
270	  <div class="pane" id="s-work">
271	    <h2>One moment.</h2>
272	    <p class="progress-text" id="progress">Copying your voice and reading your answers.</p>
273	    <p class="error-msg" id="e-work"></p>
274	    <button class="btn btn-outline" id="retry" hidden>Record again</button>
275	  </div>
276	
277	  <!-- 4: Confirm -->
278	  <div class="pane" id="s-confirm">
279	    <button class="btn-back" onclick="backToRecord()">&larr; Record again</button>
280	    <h2>Did we get this right?</h2>
281	    <p class="subtitle">Fix anything that's wrong. Where a box is empty, we use a typical value for your age.</p>
282	    <details><summary>What we heard</summary><p id="transcript"></p></details>
283	    <div class="grid" id="fields"></div>
284	    <p class="error-msg" id="e-confirm"></p>
285	    <button class="btn btn-primary" id="confirm">This looks right</button>
286	  </div>
287	
288	  <!-- 5: Ready -->
289	  <div class="pane" id="s-done">
290	    <h2>Your future self is ready.</h2>
291	    <p class="subtitle" id="done-note">Put the headset on and say hello.</p>
292	    <div class="btn-row">
293	      <a class="btn btn-primary" id="open-xr" href="#">Open in the headset</a>
294	      <a class="btn btn-outline" id="open-laptop" href="/dev.html">Talk on this screen</a>
295	    </div>
296	    <p class="quiet" style="margin-top: 20px" id="head-note"></p>
297	  </div>
298	
299	</div>
300	
301	<button class="sound-toggle" id="sound-toggle">Sound on</button>
302	
303	<footer></footer>
304	
305	<script>
306	const $ = id => document.getElementById(id);
307	const say = (id, t) => { $(id).textContent = t || ""; };
308	
309	// ---- Pane transitions ----
310	let current = "s-hero";
311	function show(id) {
312	  const old = $(current);
313	  const next = $(id);
314	  if (old === next) return;
315	  old.classList.remove("on");
316	  next.classList.add("entering");
317	  void next.offsetWidth;
318	  setTimeout(() => {
319	    next.classList.remove("entering");
320	    next.classList.add("on");
321	    current = id;
322	  }, 420);
323	}
324	
325	// ---- Pad synth ----
326	let padCtx, padGain, padStarted = false;
327	function startPad() {
328	  if (padStarted) return;
329	  padStarted = true;
330	  padCtx = new AudioContext();
331	  padGain = padCtx.createGain();
332	  padGain.gain.value = 0;
333	  padGain.connect(padCtx.destination);
334	
335	  const filter = padCtx.createBiquadFilter();
336	  filter.type = "lowpass";
337	  filter.frequency.value = 500;
338	  filter.Q.value = 0.7;
339	  filter.connect(padGain);
340	
341	  const lfo = padCtx.createOscillator();
342	  const lfoGain = padCtx.createGain();
343	  lfo.frequency.value = 0.08;
344	  lfoGain.gain.value = 150;
345	  lfo.connect(lfoGain);
346	  lfoGain.connect(filter.frequency);
347	  lfo.start();
348	
349	  const notes = [110, 164.81, 220, 329.63];
350	  for (const freq of notes) {
351	    for (const detune of [-4, 0, 4]) {
352	      const osc = padCtx.createOscillator();
353	      osc.type = "triangle";
354	      osc.frequency.value = freq;
355	      osc.detune.value = detune;
356	      osc.connect(filter);
357	      osc.start();
358	    }
359	  }
360	  padGain.gain.linearRampToValueAtTime(0.035, padCtx.currentTime + 3);
361	  $("sound-toggle").textContent = "Sound on";
362	}
363	
364	let padMuted = false;
365	$("sound-toggle").onclick = () => {
366	  if (!padStarted) { startPad(); return; }
367	  padMuted = !padMuted;
368	  padGain.gain.linearRampToValueAtTime(padMuted ? 0 : 0.035, padCtx.currentTime + 0.5);
369	  $("sound-toggle").textContent = padMuted ? "Sound off" : "Sound on";
370	};
371	
372	// ---- Hero ----
373	$("begin").onclick = () => {
374	  startPad();
375	  show("s-name");
376	};
377	
378	// ---- Name ----
379	let name = "";
380	$("to-record").onclick = () => {
381	  name = $("name").value.trim();
382	  if (!name) return say("e-name", "Please type your name.");
383	  say("e-name", "");
384	  show("s-record");
385	};
386	$("name").addEventListener("keydown", e => e.key === "Enter" && $("to-record").click());
387	
388	// ---- Record ----
389	let recorder, chunks = [], stream, tick, started = 0;
390	const fmt = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
391	
392	$("rec-start").onclick = async () => {
393	  say("e-record", "");
394	  try {
395	    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
396	  } catch {
397	    return say("e-record", "The microphone is blocked. Allow it in your browser and try again.");
398	  }
399	  chunks = [];
400	  recorder = new MediaRecorder(stream);
401	  recorder.ondataavailable = e => e.data.size && chunks.push(e.data);
402	  recorder.onstop = upload;
403	  recorder.start();
404	  started = performance.now();
405	  $("rec-start").disabled = true;
406	  $("rec-stop").disabled = false;
407	  tick = setInterval(() => {
408	    const s = Math.round((performance.now() - started) / 1000);
409	    $("timer").textContent = fmt(s);
410	    $("rec-hint").textContent = s < 30 ? "Keep going. About a minute is ideal." : "Good. Stop whenever you've covered the questions.";
411	    if (s >= 90) stop();
412	  }, 500);
413	};
414	
415	function stop() {
416	  clearInterval(tick);
417	  if (recorder && recorder.state !== "inactive") recorder.stop();
418	  stream?.getTracks().forEach(t => t.stop());
419	  $("rec-stop").disabled = true;
420	}
421	$("rec-stop").onclick = stop;
422	
423	// ---- Upload: voice clone + field extraction in parallel ----
424	let reading = null, voiceOk = true, voiceProblem = "";
425	async function upload() {
426	  show("s-work");
427	  say("e-work", "");
428	  $("retry").hidden = true;
429	  const blob = new Blob(chunks, { type: recorder.mimeType || "audio/webm" });
430	  const post = url => fetch(url, { method: "POST", headers: { "content-type": blob.type }, body: blob });
431	  let cloneRes, readRes;
432	  try {
433	    [cloneRes, readRes] = await Promise.all([
434	      post("/api/voice/clone?name=" + encodeURIComponent(name)),
435	      post("/api/interview/extract"),
436	    ]);
437	  } catch {
438	    return failed("Could not reach the server. Check your connection and record again.");
439	  }
440	  const c = await cloneRes.json().catch(() => ({}));
441	  reading = await readRes.json().catch(() => ({}));
442	  if (!readRes.ok) return failed("Could not read your answers: " + (reading.error || readRes.status));
443	  voiceOk = cloneRes.ok;
444	  voiceProblem = cloneRes.ok ? "" : "Your voice could not be copied (" + (c.error || cloneRes.status) + "), so Uncle will use a stock voice.";
445	  showConfirm(reading);
446	}
447	
448	function failed(msg) {
449	  say("e-work", msg);
450	  say("progress", "");
451	  $("retry").hidden = false;
452	}
453	$("retry").onclick = () => { backToRecord(); };
454	function backToRecord() { $("timer").textContent = "0:00"; $("rec-start").disabled = false; show("s-record"); }
455	
456	// ---- Confirm ----
457	const ROWS = [
458	  ["age", "Age", "number"], ["sex", "Sex", "select:male,female"], ["province", "Province", "text"],
459	  ["income_per_year", "Income/year ($)", "number"], ["savings.tfsa", "TFSA ($)", "number"],
460	  ["savings.rrsp", "RRSP ($)", "number"], ["savings.other", "Other savings ($)", "number"],
461	  ["saving_per_month", "Saving/month ($)", "number"], ["retirement_age", "Retire at", "number"],
462	  ["habits.exercise_per_week", "Workouts/week", "number"], ["habits.sleep_hours", "Sleep (hours)", "number"],
463	  ["habits.smoker", "Smoker", "select:no,yes"], ["habits.drinks_per_week", "Drinks/week", "number"],
464	];
465	const getPath = (o, p) => p.split(".").reduce((a, k) => a == null ? a : a[k], o);
466	const setPath = (o, p, v) => { const ks = p.split("."); const last = ks.pop(); ks.reduce((a, k) => (a[k] ??= {}), o)[last] = v; };
467	
468	function showConfirm(r) {
469	  $("transcript").textContent = r.transcript || "";
470	  $("fields").replaceChildren();
471	  for (const [path, label, type] of ROWS) {
472	    const heard = getPath(r.heard || {}, path);
473	    const row = document.createElement("label");
474	    row.className = "field";
475	    const span = document.createElement("span");
476	    span.className = "label-text";
477	    span.textContent = label;
478	    row.append(span);
479	    let input;
480	    if (type.startsWith("select:")) {
481	      input = document.createElement("select");
482	      const blank = document.createElement("option");
483	      blank.value = ""; blank.textContent = "Not said";
484	      input.append(blank);
485	      for (const o of type.slice(7).split(",")) input.append(new Option(o, o));
486	      input.value = heard == null ? "" : typeof heard === "boolean" ? (heard ? "yes" : "no") : heard;
487	    } else {
488	      input = document.createElement("input");
489	      input.type = type;
490	      input.placeholder = "Not said";
491	      input.value = heard ?? "";
492	    }
493	    input.dataset.path = path;
494	    row.append(input);
495	    $("fields").append(row);
496	  }
497	  say("e-confirm", [voiceProblem, r.rejected?.length ? "Could not parse: " + r.rejected.join(", ") : ""].filter(Boolean).join(" "));
498	  show("s-confirm");
499	}
500	
501	let savedSex = "";
502	$("confirm").onclick = async () => {
503	  const profile = {};
504	  for (const el of document.querySelectorAll("#fields [data-path]")) {
505	    let v = el.value.trim();
506	    if (v === "") v = null;
507	    else if (el.dataset.path === "habits.smoker") v = v === "yes";
508	    else if (el.type === "number") v = Number(v);
509	    setPath(profile, el.dataset.path, v);
510	  }
511	  savedSex = profile.sex || "";
512	  $("confirm").disabled = true;
513	  const res = await fetch("/api/interview/confirm", {
514	    method: "POST",
515	    headers: { "content-type": "application/json" },
516	    body: JSON.stringify({ name, profile, speech: $("transcript").textContent }),
517	  }).catch(() => null);
518	  const j = res ? await res.json().catch(() => ({})) : {};
519	  $("confirm").disabled = false;
520	  if (!res || !res.ok) return say("e-confirm", "Could not save: " + (j.error || (res ? res.status : "no connection")));
521	  finish();
522	};
523	
524	// ---- Done: hand off to headset ----
525	async function finish() {
526	  const params = new URLSearchParams({ voice: "live", name });
527	  if (savedSex) params.set("sex", savedSex);
528	  let headNote = "No head scan saved yet. The headset will show a stand-in face, but the voice and numbers are yours.";
529	  try {
530	    const { heads } = await (await fetch("/api/heads?q=" + encodeURIComponent(name))).json();
531	    const match = (heads || []).find(h => h.name.toLowerCase() === name.toLowerCase());
532	    if (match) { params.set("head", match.id); headNote = "Your saved head scan will appear across the table."; }
533	  } catch {}
534	  $("open-xr").href = "/xr/?" + params;
535	  $("open-laptop").href = "/dev.html?name=" + encodeURIComponent(name);
536	  say("head-note", headNote + (voiceOk ? "" : " " + voiceProblem));
537	  show("s-done");
538	}
539	</script>
540	</body>
541	</html>
