/* Evolution sketch sprites */
.evo-sprite {
  position: fixed;
  pointer-events: none;
  z-index: -1;
  background: url('/evolution.jpg') no-repeat;
  mix-blend-mode: multiply;
  opacity: 0;
  animation: evo-life 8s ease forwards;
}
@keyframes evo-life {
  0%   { opacity: 0; clip-path: inset(100% 0 0 0); transform: translateY(0); }
  15%  { opacity: 0.35; clip-path: inset(0); }
  60%  { opacity: 0.25; }
  100% { opacity: 0; transform: translateY(-30px); }
}

/* Warm ambient washes — not circles, not pastel */

