input.new_string:
// ---- Evolution sketches ----
const EVO_FIGURES = [
  { x: 0,   y: 55, w: 8,  h: 40 },
  { x: 6,   y: 55, w: 10, h: 40 },
  { x: 14,  y: 50, w: 12, h: 45 },
  { x: 25,  y: 45, w: 12, h: 50 },
  { x: 36,  y: 35, w: 14, h: 60 },
  { x: 50,  y: 20, w: 15, h: 75 },
  { x: 65,  y: 10, w: 15, h: 85 },
  { x: 80,  y: 5,  w: 18, h: 90 },
];
function spawnSketch() {
  const fig = EVO_FIGURES[Math.random() * EVO_FIGURES.length | 0];
  const el = document.createElement("div");
  el.className = "evo-sprite";
  const scale = 0.6 + Math.random() * 0.4;
  const w = fig.w * 10 * scale;
  const h = fig.h * 4 * scale;
  el.style.width = w + "px";
  el.style.height = h + "px";
  el.style.backgroundSize = (100 / fig.w * 100) + "% " + (100 / fig.h * 100) + "%";
  el.style.backgroundPosition = (fig.x / (100 - fig.w) * 100) + "% " + (fig.y / (100 - fig.h) * 100) + "%";
  el.style.left = (Math.random() * 70 + 5) + "vw";
  el.style.top = (Math.random() * 60 + 10) + "vh";
  document.body.appendChild(el);
  el.addEventListener("animationend", () => el.remove());
}
setInterval(spawnSketch, 4000);
setTimeout(spawnSketch, 1500);

// ---- Hero ----

